/* 1. Static: default flow; top, right, bottom, left properties have NO effect */
.default-element {
  position: static;
}

/* 2. Relative: element is positioned relative to its normal position */
.nudged-element {
  position: relative;
  top: -10px;
  left: 15px;
  /* The original space occupied by this element in the document flow remains reserved! */
  background-color: #fef08a;
}

/* Parent container must be positioned (relative) to establish the containing block */
.notification-card {
  position: relative;
  width: 350px;
  padding: 1.5rem;
  background-color: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
}

/* Absolute child: pinned relative to the edges of .notification-card */
.close-button {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 24px;
  height: 24px;
  cursor: pointer;
  background: none;
  border: none;
}

.back-to-top-btn {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 1000;

  padding: 12px 18px;
  background-color: #2563eb;
  color: #ffffff;
  border: none;
  border-radius: 50px;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.4);
  cursor: pointer;
}

.sticky-table-header {
  /* Acts as relative until the user scrolls past its threshold, then sticks like fixed */
  position: sticky;
  top: 0;
  z-index: 10;

  background-color: #0f172a;
  color: #ffffff;
  padding: 12px 16px;
}

/* Note: Sticky positioning requires at least one threshold (top, bottom, left, right) 
   and fails if any parent element has overflow: hidden */
